fn single_try_engage(&mut self, version, rnd, player, data, target_id, debug) -> Option<SinglePlanBattle>   // modes.rs:241

game = *data.cache                                       // &AbstractGameWithCache(8840B)
entity_of = |id| (game.vtable[+0x1f0])(game.data, id)    // Option<&Entity(1728B)>

// [242] closure$0 + Option::is_some_and
in_tower = match entity_of(target_id) {
    None    => false,
    Some(e) => tower_discipline::engage_requires_dive(player, data, e)
}

// [243] in_tower 로 갈리는 두 갈래로 battle 생성
if !in_tower {
    // [253]
    battle = SinglePlanBattle::new(version, BattlePlanGoal::TryKill(target_id, 60), data, player)
} else {
    // [244] 재조회. 여기서 None 이면 그대로 함수 종료(None)
    let Some(target) = entity_of(target_id) else { return None }

    // [245] 다이브가 성립하는지 게이트. false 면 즉시 None
    if !single_battle::single_tower_dive_is_viable(version, rnd, player, data,
                                                  &mut self.team_plan /*+0xf8*/, target, debug) {
        return None
    }

    // [248]
    let mut b = SinglePlanBattle::new_dive(version, BattlePlanGoal::TryKill(target_id, 60), data, player)

    // [249~250] 다이브해서 들이받을 타워를 고른다
    b.dive_tower /*+0x8c, i8*/ =
        game.iter_towers_without_nexus(1 - player.info.team /*+0x930*/)   // 상대팀 타워(넥서스 제외)
            .min_by_key(|t| t.distance_sq(target))    // target 과의 (dx^2+dy^2) 최소. abs_diff 로 무부호 계산
            .and_then(|x| if x.ty /*+0x68*/ == EntityType::Tower(2) {
                              Some(x.ty.Tower.info.ty /*+0x128, TowerType*/)
                          } else { None });           // None 이면 -1 저장

    // [251]
    battle = b
}

// [255] 만든 플랜을 실제로 한 번 굴린다 (여기서 sub_goal 이 확정된다)
battle.update(version, rnd, player, data,
              &self.positioning_score /*+0x990, 2760B*/, &mut self.team_plan /*+0xf8*/, debug)

// [256] 커밋 판정 — 굴려본 결과가 '도주/종료' 계열이면 이 교전 자체를 채택하지 않는다
committed = !matches!(battle.sub_goal /*+0x58*/, KitingBack | RunAway | End)   // 3 | 4 | 7

if committed {
    Some(battle)          // 144B 를 sret 로 memcpy
} else {
    // [257] 판별자 -1(None) 을 쓰고 battle.chats(Vec<Chat>, +0x68) 만 명시적으로 drop
    None
}

[호출 형태 주의] 아래는 IR 에서 `call` 이 아니라 `invoke`(언와인드 경로 있음)라 calls 배열엔 넣지 않았다:
  - game_core::simulation::AbstractGameWithCache::iter_towers_without_nexus (line 249)
  - Copied<slice::Iter<&Entity>>::next (min_by_key 첫 원소를 수동 전진시키는 부분)
  - Iterator::min_by_key -> min_by -> fold 단일 특수화 심볼 (첫 원소와 첫 키를 인자로 받아 나머지를 접는 형태)
  - SinglePlanBattle::update (line 255)
  - Vec<Chat>::drop / RawVec<Chat>::drop (line 257 포기 경로)
엔티티 조회는 vtable 간접호출이라 심볼이 없다.

[언와인드] cleanuppad 2개: 249~250 구간에서 언와인드하면 임시 b 를, 255(update)에서 언와인드하면 battle 을 drop_glue<SinglePlanBattle> 로 정리한다.

[구조 요약] 이 함수는 '교전 후보를 실제 플랜으로 만들어 1틱 시뮬해보고, 결과가 마음에 안 들면 통째로 버리는' 시험(try) 패턴이다. 실질 판정은 (a) 242행 다이브 필요 여부, (b) 245행 다이브 성립 여부, (c) 255행 update 가 내놓는 sub_goal, 이 셋에 있다.
